import sys


def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    edges = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(m)]
    best = -1
    best_v = -1
    for x in range(n):
        root = list(range(n))

        def find(a):
            while root[a] != a:
                root[a] = root[root[a]]
                a = root[a]
            return a

        for u, v in edges:
            if u == x or v == x:
                continue
            ru, rv = find(u), find(v)
            if ru != rv:
                root[ru] = rv
        total = sum(1 for v in range(n) if v != x and find(v) == v)
        if total > best:
            best = total
            best_v = x
    print(best, best_v)


main()
